INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d74e36fd-1550-42bf-a471-75f292b882a0', 'b2b2b2b2-3030-4000-8000-000000000002', 26, 'Dia 26 — Alegria', 'Semana 4: Integrar', '{"pch": "A alegria do Senhor \u00e9 a vossa for\u00e7a\u2026 A alegria n\u00e3o nega a dor \u2014 coexiste com ela.", "verse": "Ne 8,10", "lectio": "Leia Ne 8,9-12. Chorar e celebrar no mesmo dia.", "practice": "Fa\u00e7a algo que te d\u00ea alegria pura hoje.", "question": "O que te d\u00e1 alegria verdadeira?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;